command(Add-Type @"
  using System;
  using System.Text;
  using System.Runtime.InteropServices;
  public class WindowHelper {
    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
    [DllImport("user32.dll")]
    public static extern bool IsWindowVisible(IntPtr hWnd);
    [DllImport("user32.dll", SetLastError=true)]
    public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
  }
"@
$titles = @()
[WindowHelper]::EnumWindows({
  param($hwnd, $lparam)
  if ([WindowHelper]::IsWindowVisible($hwnd)) {
    $sb = New-Object System.Text.StringBuilder 512
    $len = [WindowHelper]::GetWindowText($hwnd, $sb, 512)
    if ($len -gt 0) {
      $pid = 0
      [WindowHelper]::GetWindowThreadProcessId($hwnd, [ref]$pid)
      $proc = Get-Process -Id $pid -ErrorAction SilentlyContinue
      $script:titles += [PSCustomObject]@{
        Hwnd = $hwnd
        Pid = $pid
        Process = $proc.ProcessName
        Title = $sb.ToString()
      }
    }
  }
  return $true
}, [IntPtr]::Zero) | Out-Null
$titles | Where-Object { $_.Title -notmatch '^(Default IME|MSCTFIME UI)$' } | Format-Table -AutoSize)

command(Get-ChildItem -Path "$env:LOCALAPPDATA\Google\Chrome Dev\User Data\Default\Extensions" -Directory | ForEach-Object {
    $manifestPath = Get-ChildItem -Path $_.FullName -Recurse -Filter "manifest.json" | Select-Object -First 1
    if ($manifestPath) {
        $json = Get-Content -Raw $manifestPath.FullName | ConvertFrom-Json
        [PSCustomObject]@{
            Id = $_.Name
            Name = $json.name
            Description = $json.description
        }
    }
} | Format-Table -AutoSize)
